#include <iostream>

int main() {
    int count = 7;
    // Khai bao don le va khoi tao an toan bang nullptr theo chuan C++17
    int* countPtr = nullptr;

    std::cout << "Trang thai ban dau: ";
    if (countPtr == nullptr) {
        std::cout << "countPtr dang tro toi nullptr (khong tro vao dau)\n";
    }

    // Gan dia chi cua count vao countPtr
    countPtr = &count;

    std::cout << "Sau khi gan dia chi:\n";
    std::cout << "countPtr da hop le: " << (countPtr != nullptr ? "dung" : "sai") << "\n";
    std::cout << "Gia tri cua count truy cap truc tiep: " << count << "\n";
    std::cout << "Gia tri cua count truy cap gian tiep qua countPtr: " << *countPtr << "\n";

    return 0;
}

#include <iostream>

int main() {
    int a = 7;
    int* aPtr = &a; // aPtr luu dia chi cua a

    std::cout << "Gia tri a ban dau: " << a << "\n";
    std::cout << "Gia tri a qua dereference *aPtr: " << *aPtr << "\n";

    // Thay doi gia tri a bang cach ghi qua *aPtr
    *aPtr = 25;
    std::cout << "Gia tri a sau khi sua qua *aPtr: " << a << "\n";

    // Kiem tra tinh chat bu tru: *&aPtr va &*aPtr co bang aPtr hay khong
    bool test1 = ((void*)(&*aPtr) == (void*)aPtr);
    bool test2 = ((void*)(*&aPtr) == (void*)aPtr);

    std::cout << "&*aPtr bang aPtr: " << (test1 ? "dung" : "sai") << "\n";
    std::cout << "*&aPtr bang aPtr: " << (test2 ? "dung" : "sai") << "\n";

    return 0;
}
